(async()=>{
 const root=document.getElementById('paper-results'),el=(tag,text,cls)=>{const n=document.createElement(tag);if(text)n.textContent=text;if(cls)n.className=cls;return n};
 try{const response=await fetch('paper/analysis.json');if(!response.ok)throw Error();const d=await response.json();
 const figures=[['04-controlled-comparison','1 · Same evidence, different summaries','All eight eligible completed runs are shown. Direct: 3 and 2 incorrect claim counts; structured: 3 and 3; staged: 1 and 2; exact-table control: 0 and 0, out of 15 in each output. The control has privileged information. This suggests a useful intervention to test, not an established general improvement.'],['05-threshold-sensitivity','2 · Could a counting error change what gets flagged?','Yes, for some thresholds in this case. The curves compare a mechanical support threshold using recorded versus reported counts. They are not observed human decisions, and do not measure decision loss.'],['06-archive-accounting','3 · Account for every available run','The snapshot contains completed, failed and scheduled records. Only the eight matching v8 transcript runs enter this comparison. Failed product runs prevent a balanced platform comparison. The earlier v7 case studies remain separate.']];
 for(const [file,title,caption] of figures){const a=el('article',null,'figure');a.append(el('h3',title));const link=el('a');link.href=`paper/${file}.svg`;link.target='_blank';const img=el('img');img.src=link.href;img.alt=caption;link.append(img);a.append(link,el('p',caption));const links=el('div',null,'downloads');for(const ext of ['svg','pdf','png']){const l=el('a',ext==='png'?'600 dpi PNG':ext.toUpperCase());l.href=`paper/${file}.${ext}`;links.append(l)}a.append(links);root.append(a)}
 const detail=el('details');detail.append(el('summary','Inspect all eight outputs and their claim-level discrepancies'));for(const s of d.summary){const item=el('details');item.append(el('summary',`${s.method} · repeat ${s.repeat+1} · ${s.mismatches}/15 claim counts differ`));for(const r of d.rows.filter(r=>r.method===s.method&&r.repeat===s.repeat)){const p=el('p',`${r.claim}: recorded ${r.recorded.join('/')} → reported ${r.reported.join('/')} ${r.mismatch?' · DIFFERENT':' · exact'}`);item.append(p,el('blockquote',r.quote))}detail.append(item)}root.append(detail);
 }catch(e){root.textContent='The matched analysis could not load. The downloadable evidence remains available below.'}
})();
